package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import com.google.mlkit.vision.barcode.common.Barcode;import java.io.*;import java.util.*;import org.json.*;
/** Additional actual model families within the same comparison/report contract. */
final class SupplementalImageRunner {
 private SupplementalImageRunner(){}
 static boolean supports(String f,String id){return "segment".equals(f)&&("selfie-segmentation".equals(id)||"deeplab-v3".equals(id))||"classify".equals(f)&&id.startsWith("efficientnet-")||"pose".equals(f)&&(id.startsWith("movenet-")||PlusPoseEngine.supports(id))||"qr".equals(f)&&"mlkit-barcode".equals(id);}
 static OneModelRunner.Result run(Context c,String f,String id,Bitmap input,OneModelRunner.Cancel cancel){
  if("segment".equals(f))return segmentation(c,id,input,cancel);OneModelRunner.Result r=new OneModelRunner.Result(f,id);long start=SystemClock.elapsedRealtime();AutoCloseable engine=null;
  try{check(cancel);r.image=input.copy(Bitmap.Config.ARGB_8888,true);if(r.image==null)throw new IOException("사진 준비 실패");Canvas canvas=new Canvas(r.image);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(0xff0068f8);paint.setStrokeWidth(Math.max(2,input.getWidth()/260f));long load=SystemClock.elapsedRealtime();
   if("classify".equals(f)){
    OneEfficientNet model=new OneEfficientNet(c,id);engine=model;r.modelSha256=model.sha256;r.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();float[] scores=model.classify(input);r.inferenceMs=SystemClock.elapsedRealtime()-infer;check(cancel);List<String> labels=new ArrayList<>();OneObjectEngine.read(c,"one/models/"+id+".tflite.labels_without_background.txt",labels);if(labels.size()!=1000)throw new IOException("ImageNet labels");List<Integer> order=new ArrayList<>();for(int i=0;i<1000;i++)order.add(i);order.sort((a,b)->Float.compare(scores[b],scores[a]));JSONArray top=new JSONArray();StringBuilder detail=new StringBuilder();for(int i=0;i<5;i++){int j=order.get(i);top.put(new JSONObject().put("classId",j).put("label",labels.get(j)).put("score",scores[j]));detail.append(labels.get(j)).append(" · ").append(String.format(Locale.ROOT,"%.1f%%",scores[j]*100)).append('\n');}r.metrics.put("top5",top).put("normalizationMean",127).put("normalizationStd",128).put("quantizedInput",id.endsWith("i8")).put("centerCrop",true);r.summary=labels.get(order.get(0));r.detail=detail.toString();
   }else if("pose".equals(f)){
    boolean plus=PlusPoseEngine.supports(id);PlusPoseEngine added=plus?new PlusPoseEngine(c,id):null;OneMoveNetEngine model=plus?null:new OneMoveNetEngine(c,id);engine=plus?added:model;r.modelSha256=plus?added.sha256:model.sha256;r.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();List<PoseGeometry.Point> points=plus?added.pose(input):model.pose(input);r.inferenceMs=SystemClock.elapsedRealtime()-infer;check(cancel);paint.setColor(0xff0f9f6e);for(PoseGeometry.Point[] edge:PoseGeometry.edges(points))canvas.drawLine(edge[0].x*input.getWidth(),edge[0].y*input.getHeight(),edge[1].x*input.getWidth(),edge[1].y*input.getHeight(),paint);for(PoseGeometry.Point p:PoseGeometry.visible(points))canvas.drawCircle(p.x*input.getWidth(),p.y*input.getHeight(),Math.max(3,input.getWidth()/160f),paint);r.metrics.put("landmarks",points.size()).put("visibleLandmarks",PoseGeometry.visible(points).size()).put("points",points(points));r.summary="관측 지점 "+PoseGeometry.visible(points).size()+"개";
   }else{
    OneBarcodeEngine model=new OneBarcodeEngine();engine=model;r.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();List<Barcode> found=model.analyze(input);r.inferenceMs=SystemClock.elapsedRealtime()-infer;check(cancel);JSONArray codes=new JSONArray();StringBuilder text=new StringBuilder();for(Barcode b:found){String value=b.getRawValue();if(value==null||value.isEmpty())continue;String format=OneBarcodeEngine.format(b.getFormat());codes.put(new JSONObject().put("format",format).put("value",value));if(text.length()>0)text.append('\n');text.append(value);Rect box=b.getBoundingBox();if(box!=null){paint.setStyle(Paint.Style.STROKE);canvas.drawRect(box,paint);}}r.metrics.put("codes",codes).put("characters",text.length()).put("sdk","com.google.mlkit:barcode-scanning:17.3.0");r.summary=codes.length()>0?codes.getJSONObject(0).getString("format")+" · "+codes.length()+"개":"코드 없음";r.detail=text.toString();
   }
   check(cancel);r.state="COMPLETED";
  }catch(Exception|LinkageError|OutOfMemoryError e){r.state=cancel.canceled()||Thread.currentThread().isInterrupted()?"CANCELED":"ERROR";r.errorType=e.getClass().getSimpleName();r.summary=r.state.equals("CANCELED")?"분석 취소":"다른 모델로 다시 분석하세요";android.util.Log.w("YOn","supplemental_"+f,e);}
  finally{r.engineCreated=engine!=null;r.engineCloseReturned=engine==null;try{if(engine!=null){engine.close();r.engineCloseReturned=!(engine instanceof OneBarcodeEngine)||((OneBarcodeEngine)engine).closed();}}catch(Exception|LinkageError e){r.state="ERROR";r.errorType=e.getClass().getSimpleName();}r.elapsedMs=SystemClock.elapsedRealtime()-start;}
  return r;
 }
 private static OneModelRunner.Result segmentation(Context c,String id,Bitmap input,OneModelRunner.Cancel cancel){OneModelRunner.Result r=new OneModelRunner.Result("segment",id);long started=SystemClock.elapsedRealtime();try{check(cancel);if("selfie-segmentation".equals(id))BackgroundStudio.segment(c,input,cancel,r);else{long load=SystemClock.elapsedRealtime();try(OneDeepLabEngine model=new OneDeepLabEngine(c)){r.engineCreated=true;r.modelSha256=model.sha256;r.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();model.segment(input,cancel,r);r.inferenceMs=SystemClock.elapsedRealtime()-infer;}r.engineCloseReturned=true;}check(cancel);r.state="COMPLETED";}catch(Exception|LinkageError|OutOfMemoryError e){r.state=cancel.canceled()?"CANCELED":"ERROR";r.errorType=e.getClass().getSimpleName();r.summary=r.state.equals("CANCELED")?"분석 취소":"다른 모델로 다시 분석하세요";android.util.Log.w("YOn","segmentation",e);}finally{r.elapsedMs=SystemClock.elapsedRealtime()-started;}return r;}
 static JSONArray points(List<PoseGeometry.Point> points)throws JSONException{JSONArray a=new JSONArray();for(PoseGeometry.Point p:points)if(Float.isFinite(p.x)&&Float.isFinite(p.y)&&Float.isFinite(p.likelihood))a.put(new JSONObject().put("id",p.id).put("x",p.x).put("y",p.y).put("score",p.likelihood));return a;}
 private static void check(OneModelRunner.Cancel c)throws InterruptedIOException{if(c.canceled()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("canceled");}
}
